import React, { useState, useEffect } from 'react';
import { Chart } from 'primereact/chart';

export default function Pie() {
    const [chartData, setChartData] = useState({});
    const [chartOptions, setChartOptions] = useState({});

    useEffect(() => {
        const targetElement = document.body ?? document.documentElement;
        const documentStyle = getComputedStyle(targetElement);
        const getColor = (variable) => {
            const value = documentStyle.getPropertyValue(variable)?.trim();
            if (value) {
                return value;
            }

            const rootStyle = getComputedStyle(document.documentElement);
            const rootValue = rootStyle.getPropertyValue(variable)?.trim();
            return rootValue;
        };

        const data = {
            labels: ['A', 'B', 'C'],
            datasets: [
                {
                    data: [540, 325, 702],
                    backgroundColor: [
                        getColor('--uls-primary-color'),
                        getColor('--uls-warning-color'),
                        getColor('--uls-success-color')
                    ],
                    hoverBackgroundColor: [
                        getColor('--uls-primary-hover-color'),
                        getColor('--uls-warning-hover-color'),
                        getColor('--uls-success-hover-color')
                    ]
                }
            ]
        }
        const options = {
            plugins: {
                legend: {
                    labels: {
                        usePointStyle: true
                    }
                }
            }
        };

        setChartData(data);
        setChartOptions(options);
    }, []);

    return (
        <div className="fxb fvc fhc">
            <Chart type="pie" data={chartData} options={chartOptions} className="w300" />
        </div>
    )
}